import h5py, numpy as np

def deref(f, x):
    """Recursively convert h5py object to python."""
    if isinstance(x, h5py.Reference):
        return deref(f, f[x])
    if isinstance(x, h5py.Group):
        return {k: deref(f, x[k]) for k in x.keys()}
    if isinstance(x, h5py.Dataset):
        if x.dtype == object:
            arr = x[()]
            out = np.empty(arr.shape, dtype=object)
            for idx in np.ndindex(arr.shape):
                out[idx] = deref(f, arr[idx])
            return out
        a = x[()]
        if h5py.check_string_dtype(x.dtype):
            return a
        if x.dtype == np.uint16 and x.attrs.get('MATLAB_class', b'') == b'char':
            return ''.join(chr(c) for c in a.ravel())
        return a
    return x
