"""Unified loader for the Economo-lab data objects (MAT v7 and v7.3).

Provides a lazy-ish accessor with the fields needed for conversion:
  bp (hit, miss, no, early, autowater, R, L, stim.enable, ev.*)
  clu[probe] -> list of dicts with quality, trial, trialtm
  traj[view] -> per-trial dict with ts, frameTimes, NdroppedFrames, featNames
  sglx.fs, sglx.bitcode.bitstart
  ex.probe.loc
"""
import numpy as np
import h5py
import scipy.io as sio


def is_hdf5(fn):
    with open(fn, 'rb') as f:
        return b'7.3' in f.read(120)


def _h5str(f, ref):
    o = f[ref] if isinstance(ref, h5py.Reference) else ref
    a = np.asarray(o[()]).ravel()
    try:
        return ''.join(chr(int(c)) for c in a)
    except Exception:
        return ''


class Session:
    def __init__(self, fn):
        self.fn = fn
        self.hdf5 = is_hdf5(fn)
        if self.hdf5:
            self.f = h5py.File(fn, 'r')
            self.obj = self.f['obj']
        else:
            m = sio.loadmat(fn, struct_as_record=False, squeeze_me=True)
            self.obj = m['obj']

    # ---------- generic helpers ----------
    def bpvec(self, name):
        """1-D per-trial vector from obj.bp.<name> (supports 'stim/enable')."""
        if self.hdf5:
            return np.asarray(self.obj['bp/' + name][()]).ravel()
        o = self.obj.bp
        for part in name.split('/'):
            o = getattr(o, part)
        return np.asarray(o).ravel()

    def ev(self, name):
        if self.hdf5:
            return np.asarray(self.obj['bp/ev/' + name][()]).ravel()
        return np.asarray(getattr(self.obj.bp.ev, name)).ravel()

    def ev_cell(self, name):
        """lickL / lickR: list of arrays per trial."""
        out = []
        if self.hdf5:
            refs = self.obj['bp/ev/' + name][()].ravel()
            for r in refs:
                d = self.f[r]
                a = np.asarray(d[()]).ravel()
                if d.attrs.get('MATLAB_empty', 0) == 1 or d.attrs.get('MATLAB_class', b'') == b'canonical empty':
                    a = np.array([])
                out.append(a.astype(float))
        else:
            cell = getattr(self.obj.bp.ev, name)
            for x in cell:
                out.append(np.atleast_1d(np.asarray(x, dtype=float)).ravel())
        return out

    @property
    def ntrials(self):
        if self.hdf5:
            return int(np.asarray(self.obj['bp/Ntrials'][()]).ravel()[0])
        return int(self.obj.bp.Ntrials)

    def has_bp_field(self, name):
        if self.hdf5:
            return name in self.obj['bp']
        return name in self.obj.bp._fieldnames

    # ---------- clusters ----------
    def nprobes(self):
        if self.hdf5:
            return self.obj['clu'][()].shape[0]
        clu = self.obj.clu
        # v7: either struct array (1 probe) or object array of struct arrays
        if isinstance(clu, np.ndarray) and clu.dtype == object:
            return len(clu)
        return 1

    def clusters(self, prb):
        """Return list of dicts for probe index prb (0-based)."""
        out = []
        if self.hdf5:
            refs = self.obj['clu'][()]
            o = self.f[refs[prb, 0]]
            if not isinstance(o, h5py.Group):
                return out
            n = o['quality'].shape[0]
            qual = o['quality'][()].ravel()
            trial = o['trial'][()].ravel()
            trialtm = o['trialtm'][()].ravel()
            for i in range(n):
                out.append(dict(
                    quality=_h5str(self.f, qual[i]),
                    trial=np.asarray(self.f[trial[i]][()]).ravel(),
                    trialtm=np.asarray(self.f[trialtm[i]][()]).ravel(),
                ))
        else:
            clu = self.obj.clu
            if isinstance(clu, np.ndarray) and clu.dtype == object:
                arr = clu[prb]
            else:
                arr = clu
            arr = np.atleast_1d(arr)
            for c in arr:
                out.append(dict(
                    quality=str(c.quality),
                    trial=np.atleast_1d(np.asarray(c.trial)).ravel(),
                    trialtm=np.atleast_1d(np.asarray(c.trialtm, dtype=float)).ravel(),
                ))
        return out

    # ---------- video ----------
    def feat_names(self, view):
        if self.hdf5:
            g = self.f[self.obj['traj'][()][view, 0]]
            refs = g['featNames'][()].ravel()
            first = self.f[refs[0]][()].ravel()
            return [_h5str(self.f, r) for r in first]
        t = self.obj.traj[view]
        return [str(x) for x in np.atleast_1d(t[0].featNames)]

    def traj_trial(self, view, trix):
        """Return ts (frames,3,feat), frameTimes (frames,), NdroppedFrames."""
        if self.hdf5:
            g = self.f[self.obj['traj'][()][view, 0]]
            ts = np.asarray(self.f[g['ts'][()][trix, 0]][()])  # (feat,3,frames)
            if ts.ndim == 3:
                ts = np.transpose(ts, (2, 1, 0))
            else:
                ts = np.full((0, 3, 0), np.nan)
            ft = np.asarray(self.f[g['frameTimes'][()][trix, 0]][()]).ravel()
            nd = np.asarray(self.f[g['NdroppedFrames'][()][trix, 0]][()]).ravel()
            nd = nd[0] if nd.size else np.nan
            return ts, ft, nd
        t = self.obj.traj[view][trix]
        ts = np.asarray(t.ts, dtype=float)
        ft = np.atleast_1d(np.asarray(t.frameTimes, dtype=float)).ravel()
        nd = np.asarray(t.NdroppedFrames).ravel()
        nd = nd[0] if nd.size else np.nan
        return ts, ft, nd

    def ntraj_trials(self, view=0):
        if self.hdf5:
            g = self.f[self.obj['traj'][()][view, 0]]
            return g['ts'].shape[0]
        return len(self.obj.traj[view])

    # ---------- sglx ----------
    def vidshift(self):
        """vidFileOffset - bitStart, per findVideoOffset.m"""
        from scipy.stats import mode as _mode
        bitStart = _mode(self.ev('bitStart'), keepdims=False).mode
        if self.hdf5:
            bs = np.asarray(self.obj['sglx/bitcode/bitstart'][()]).ravel()
            fs = float(np.asarray(self.obj['sglx/fs'][()]).ravel()[0])
        else:
            bs = np.atleast_1d(np.asarray(self.obj.sglx.bitcode.bitstart, dtype=float)).ravel()
            fs = float(np.asarray(self.obj.sglx.fs).ravel()[0])
        bs = bs[~np.isnan(bs)]
        vidFileOffset = _mode(bs, keepdims=False).mode / fs
        return float(vidFileOffset - bitStart)

    def probe_locs(self):
        out = []
        if self.hdf5:
            try:
                pl = self.obj['ex/probe/loc'][()]
                for i in range(pl.shape[0]):
                    out.append(_h5str(self.f, pl[i, 0]).strip())
            except Exception:
                pass
        else:
            try:
                loc = self.obj.ex.probe.loc
                if isinstance(loc, np.ndarray):
                    out = [str(x).strip() for x in np.atleast_1d(loc)]
                else:
                    out = [str(loc).strip()]
            except Exception:
                pass
        return out

    def close(self):
        if self.hdf5:
            self.f.close()
